// HashWX 1.0 interpreter; code is generated by hashwx-rs, never synthesized per seed.
// SPDX-License-Identifier: LGPL-3.0-only
module hashwx_core (
    input  logic clk, rst,
    input  logic cfg_we,
    input  logic [7:0] cfg_addr,
    input  logic [31:0] cfg_data,
    input  logic start,
    input  logic [63:0] nonce, target,
    output logic busy, done, hit,
    output logic [63:0] hash
);
    // Compact instruction: [15:12] op, [11:9] dst, [8:6] src, [5:0] imm.
    logic [15:0] microcode [0:255];
    logic [63:0] k0,k1;
    // 16 KiB + 8-byte sentinel, 64-bit BRAM words for arbitrary-byte loads.
    logic [63:0] scratch [0:2048];
    logic [63:0] regs [0:8];
    logic [255:0] sip_state;
    logic [63:0] current_nonce, current_target;
    logic [63:0] read_lo,read_hi;
    logic [63:0] scratch_read_data;
    logic [13:0] read_addr;
    logic [7:0] pc;
    logic [8:0] snapshot_count;
    logic [2:0] snapshot_word;
    logic [5:0] budget;
    logic [3:0] init_step;
    logic [1:0] pass;
    logic memory_phase;

    typedef enum logic [3:0] {
        IDLE, INIT, FETCH, SNAPSHOT, READ0, READ1, READ2, EXEC, FINISH
    } state_t;
    state_t state;

    function automatic logic [255:0] sipround(input logic [255:0] s);
        logic [63:0] a,b,c,d;
        begin
            {d,c,b,a} = s;
            a = a + b;
            c = c + d;
            b = {b[50:0],b[63:51]};
            d = {d[47:0],d[63:48]};
            b = b ^ a;
            d = d ^ c;
            a = {a[31:0],a[63:32]};
            c = c + b;
            a = a + d;
            b = {b[46:0],b[63:47]};
            d = {d[42:0],d[63:43]};
            b = b ^ c;
            d = d ^ a;
            c = {c[31:0],c[63:32]};
            sipround = {d,c,b,a};
        end
    endfunction

    wire [15:0] instruction = microcode[pc];
    wire [3:0] opcode = instruction[15:12];
    wire [2:0] dst = instruction[11:9];
    wire [2:0] src = instruction[8:6];
    wire [5:0] imm = instruction[5:0];
    wire [2:0] branch_dst = microcode[{pc[7:3],3'b000}][11:9];
    wire [63:0] dst_value = regs[{1'b0,dst}];
    // Single physical read port: READ0 and READ1 issue two sequential
    // synchronous reads. READ1 also captures the previous low word, and
    // READ2 captures the final high word. This permits one BRAM copy.
    wire [11:0] scratch_word_addr =
        {1'b0,read_addr[13:3]} + {11'b0,(state == READ1)};
    wire [5:0] shift_bytes = {read_addr[2:0],3'b000};
    wire [63:0] scratch_source = (read_lo >> shift_bytes)
                  | (read_hi << (7'd64 - {1'b0,shift_bytes}));
    wire [63:0] source = memory_phase ? scratch_source : regs[{1'b0,src}];
    // RMCG and the regular MUL opcodes are mutually exclusive. Feed their
    // operands to one hardware multiplier instead of synthesizing two DSP trees.
    logic [63:0] modified, shifted, value;
    wire [63:0] mul_a = (opcode == 4'd3) ? dst_value : modified;
    wire [63:0] mul_b = (opcode == 4'd3) ? regs[8] : source;
    wire [63:0] mul_product = mul_a * mul_b;
    always_comb begin
        modified = dst_value;
        shifted = dst_value;
        value = dst_value;
        case (opcode)
            4'd0,4'd1,4'd2: begin
                case (opcode)
                    4'd0: modified = dst_value | {58'b0,imm};
                    4'd1: modified = dst_value ^ {58'b0,imm};
                    default: modified = dst_value + {58'b0,imm};
                endcase
                value = mul_product;
            end
            4'd3: begin
                value = (mul_product >> imm) | (mul_product << (7'd64 - {1'b0,imm}));
            end
            4'd4,4'd5,4'd6: begin
                shifted = (dst_value >> imm) | (dst_value << (7'd64 - {1'b0,imm}));
                case (opcode)
                    4'd4: value = shifted ^ source;
                    4'd5: value = shifted + source;
                    default: value = shifted - source;
                endcase
            end
            4'd7,4'd8,4'd9: begin
                shifted = $signed(dst_value) >>> imm;
                case (opcode)
                    4'd7: value = shifted ^ source;
                    4'd8: value = shifted + source;
                    default: value = shifted - source;
                endcase
            end
            4'd10,4'd11,4'd12: begin
                shifted = dst_value >> imm;
                case (opcode)
                    4'd10: value = shifted ^ source;
                    4'd11: value = shifted + source;
                    default: value = shifted - source;
                endcase
            end
            default: value = '0;
        endcase
    end

    wire [255:0] lo_mix = sipround({regs[3],regs[2],regs[1],regs[0]});
    wire [255:0] hi_mix = sipround({regs[7],regs[6],regs[5],regs[4]});
    wire [63:0] result_hash = lo_mix[255:192] ^ hi_mix[255:192] ^ regs[8];
    assign busy = state != IDLE;

    always_ff @(posedge clk) begin
        if (rst) begin
            state <= IDLE;
            done <= 0;
            hit <= 0;
            hash <= 0;
            k0 <= 0;
            k1 <= 0;
            pc <= 0;
            snapshot_count <= 0;
            snapshot_word <= 0;
            budget <= 0;
            pass <= 0;
            memory_phase <= 0;
            init_step <= 0;
            current_nonce <= 0;
            current_target <= 0;
            sip_state <= 0;
            read_addr <= 0;
            read_lo <= 0;
            read_hi <= 0;
            for (int j=0; j<9; j++) regs[j] <= 0;
        end else begin
            if (state == READ0 || state == READ1)
                scratch_read_data <= scratch[scratch_word_addr];
            if (cfg_we && state == IDLE) begin
                if (cfg_addr < 128) begin
                    microcode[{cfg_addr[6:0],1'b0}] <= cfg_data[15:0];
                    microcode[{cfg_addr[6:0],1'b1}] <= cfg_data[31:16];
                end else case (cfg_addr)
                    128: k0[31:0] <= cfg_data;
                    129: k0[63:32] <= cfg_data;
                    130: k1[31:0] <= cfg_data;
                    131: k1[63:32] <= cfg_data;
                    default: ;
                endcase
            end
            case (state)
                IDLE: if (start && !cfg_we) begin
                    current_nonce <= nonce;
                    current_target <= target;
                    sip_state <= {
                        64'h7465646279746573 ^ k1 ^ nonce,
                        64'h6c7967656e657261 ^ k0,
                        64'h646f72616e646f6d ^ k1,
                        64'h736f6d6570736575 ^ k0
                    };
                    init_step <= 0;
                    memory_phase <= 0;
                    pass <= 0;
                    pc <= 0;
                    budget <= 32;
                    snapshot_count <= 0;
                    done <= 0;
                    hit <= 0;
                    state <= INIT;
                end
                INIT: begin
                    case (init_step)
                        0: sip_state <= sipround(sip_state);
                        1: begin
                            sip_state[63:0] <= sip_state[63:0] ^ current_nonce;
                            sip_state[191:128] <= sip_state[191:128] ^ 64'hbb;
                        end
                        2,3,4,6,7,8,9: sip_state <= sipround(sip_state);
                        5: begin
                            regs[0] <= sip_state[255:192];
                            regs[1] <= sip_state[191:128];
                            regs[2] <= sip_state[127:64];
                            regs[3] <= sip_state[63:0];
                            sip_state <= sip_state ^ {k1,k0,k1,k0};
                        end
                        10: begin
                            regs[4] <= sip_state[255:192];
                            regs[5] <= sip_state[191:128];
                            regs[6] <= sip_state[127:64];
                            regs[7] <= sip_state[63:0];
                            regs[8] <= ((regs[0] ^ sip_state[255:192]) & ~64'd7) | 64'd3;
                            scratch[2048] <= ((regs[0] ^ sip_state[255:192]) & ~64'd7) | 64'd3;
                        end
                        default: ;
                    endcase
                    if (init_step == 10) state <= FETCH;
                    else init_step <= init_step + 1'b1;
                end
                FETCH: begin
                    if (!memory_phase && pc[2:0] == 0) begin
                        snapshot_word <= 0;
                        state <= SNAPSHOT;
                    end else if (memory_phase && opcode != 3) begin
                        read_addr <= regs[{1'b0,src}][13:0];
                        state <= READ0;
                    end else state <= EXEC;
                end
                SNAPSHOT: begin
                    // Each snapshot stores R7..R0 at 8 descending 64-bit words.
                    scratch[(12'd2040 - {snapshot_count,3'b000}) + {9'd0,snapshot_word}]
                        <= regs[{1'b0,(3'd7 - snapshot_word)}];
                    if (snapshot_word == 7) begin
                        snapshot_count <= snapshot_count + 1'b1;
                        state <= EXEC;
                    end else snapshot_word <= snapshot_word + 1'b1;
                end
                READ0: state <= READ1;
                READ1: begin
                    read_lo <= scratch_read_data;
                    state <= READ2;
                end
                READ2: begin
                    read_hi <= scratch_read_data;
                    state <= EXEC;
                end
                EXEC: begin
                    regs[{1'b0,dst}] <= value;
                    if (pc[2:0] != 7) begin
                        pc <= pc + 1'b1;
                        state <= FETCH;
                    end else if (budget != 0 &&
                       (pc[7:3] == 31 || !regs[{1'b0,branch_dst}][5])) begin
                        budget <= budget - 1'b1;
                        pc <= {pc[7:3],3'b000};
                        state <= FETCH;
                    end else if (pc == 255) begin
                        pc <= 0;
                        budget <= 32;
                        if (pass != 3) begin
                            pass <= pass + 1'b1;
                            state <= FETCH;
                        end else if (!memory_phase) begin
                            memory_phase <= 1;
                            pass <= 0;
                            state <= FETCH;
                        end else state <= FINISH;
                    end else begin
                        pc <= pc + 1'b1;
                        state <= FETCH;
                    end
                end
                FINISH: begin
                    hash <= result_hash;
                    hit <= (result_hash < current_target);
                    done <= 1;
                    state <= IDLE;
                end
                default: state <= IDLE;
            endcase
        end
    end
endmodule
